/* From Uiverse.io by PriyanshuGupta28 - Tags: switch, theme-switch, light switch, 3d button */
.__UIV_SCOPE__ .checkbox-wrapper-10 .tgl {
  display: none;
}

.__UIV_SCOPE__ .checkbox-wrapper-10 .tgl,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl:after,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl:before,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl *,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl *:after,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl *:before,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl + .tgl-btn {
  box-sizing: border-box;
}

.__UIV_SCOPE__ .checkbox-wrapper-10 .tgl::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl:after::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl:before::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl *::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl *:after::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl *:before::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl + .tgl-btn::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl:after::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl:before::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl *::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl *:after::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl *:before::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl + .tgl-btn::selection {
  background: none;
}

.__UIV_SCOPE__ .checkbox-wrapper-10 .tgl + .tgl-btn {
  outline: 0;
  display: block;
  width: 4em;
  height: 2em;
  position: relative;
  cursor: pointer;
  -webkit-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
  user-select: none;
}

.__UIV_SCOPE__ .checkbox-wrapper-10 .tgl + .tgl-btn:after,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl + .tgl-btn:before {
  position: relative;
  display: block;
  content: "";
  width: 50%;
  height: 100%;
}

.__UIV_SCOPE__ .checkbox-wrapper-10 .tgl + .tgl-btn:after {
  left: 0;
}

.__UIV_SCOPE__ .checkbox-wrapper-10 .tgl + .tgl-btn:before {
  display: none;
}

.__UIV_SCOPE__ .checkbox-wrapper-10 .tgl:checked + .tgl-btn:after {
  left: 50%;
}

.__UIV_SCOPE__ .checkbox-wrapper-10 .tgl-flip + .tgl-btn {
  padding: 2px;
  transition: all 0.2s ease;
  font-family: sans-serif;
  perspective: 100px;
}

.__UIV_SCOPE__ .checkbox-wrapper-10 .tgl-flip + .tgl-btn:after,
  .__UIV_SCOPE__ .checkbox-wrapper-10 .tgl-flip + .tgl-btn:before {
  display: inline-block;
  transition: all 0.4s ease;
  width: 100%;
  text-align: center;
  position: absolute;
  line-height: 2em;
  font-weight: bold;
  color: #fff;
  top: 0;
  left: 0;
  -webkit-backface-visibility: hidden;
  backface-visibility: hidden;
  border-radius: 4px;
}

.__UIV_SCOPE__ .checkbox-wrapper-10 .tgl-flip + .tgl-btn:after {
  content: attr(data-tg-on);
  background: #7802c6;
  transform: rotateY(-180deg);
}

.__UIV_SCOPE__ .checkbox-wrapper-10 .tgl-flip + .tgl-btn:before {
  background: #197dff;
  content: attr(data-tg-off);
}

.__UIV_SCOPE__ .checkbox-wrapper-10 .tgl-flip + .tgl-btn:active:before {
  transform: rotateY(-20deg);
}

.__UIV_SCOPE__ .checkbox-wrapper-10 .tgl-flip:checked + .tgl-btn:before {
  transform: rotateY(180deg);
}

.__UIV_SCOPE__ .checkbox-wrapper-10 .tgl-flip:checked + .tgl-btn:after {
  transform: rotateY(0);
  left: 0;
  background: #7e09eb;
}

.__UIV_SCOPE__ .checkbox-wrapper-10 .tgl-flip:checked + .tgl-btn:active:after {
  transform: rotateY(20deg);
}
